export async function getCommitMessagesBetween(
  base: string,
  branch: string,
  cwd: string,
): Promise<string[]> {
  const { stdout } = await execa(
    'git',
    ['log', '--format=%B%x1e', `${base}..${branch}`],
    { cwd },
  );
  return stdout
    .split('\x1e')
    .map((entry) => entry.replace(/^\n+|\n+$/g, ''))
    .filter((entry) => entry.length > 0);
}
